/**
 * Tests for the observable behaviour of {@link Undertow}, i.e. the server built by
 * {@link Undertow#builder()}, the listeners it exposes through
 * {@link Undertow#getListenerInfo()} and the lifecycle ({@link Undertow#start()} /
 * {@link Undertow#stop()}).
 */
@Timeout(90)
class UndertowTests {

    private static final String HOST = "127.0.0.1";
    private static final String KEYSTORE_PASSWORD = "password";

    /** Two HTTP/2 settings frames, base64url encoded (RFC 7540 section 3.2.1 example payload). */
    private static final String HTTP2_SETTINGS = "AAMAAABkAAQAAP__AAIAAAAA";

    private final List<Undertow> servers = new ArrayList<>();
    private final List<Closeable> resources = new ArrayList<>();

    @AfterEach
    void cleanUp() {
        for (Undertow server : servers) {
            try {
                server.stop();
            } catch (RuntimeException ignored) {
                // best effort cleanup
            }
        }
        servers.clear();
        for (Closeable resource : resources) {
            try {
                resource.close();
            } catch (IOException ignored) {
                // best effort cleanup
            }
        }
        resources.clear();
    }

    // ------------------------------------------------------------------
    // builder / lifecycle
    // ------------------------------------------------------------------

    @Test
    void builderCreatesIndependentServerInstances() {
        Undertow.Builder firstBuilder = Undertow.builder();
        Undertow.Builder secondBuilder = Undertow.builder();

        assertNotNull(firstBuilder);
        assertNotNull(secondBuilder);
        assertNotSame(firstBuilder, secondBuilder);

        Undertow first = firstBuilder.setHandler(textHandler("first")).build();
        Undertow second = secondBuilder.setHandler(textHandler("second")).build();

        assertNotNull(first);
        assertNotNull(second);
        assertNotSame(first, second);

        // nothing is started yet
        assertNull(first.getXnio());
        assertNull(first.getWorker());
        assertNull(second.getXnio());
        assertNull(second.getWorker());
    }

    @Test
    void listenerInfoIsOnlyAvailableWhileStarted() {
        Undertow server = track(Undertow.builder()
                .addHttpListener(0, HOST)
                .setHandler(textHandler("started"))
                .build());

        IllegalStateException beforeStart = assertThrows(IllegalStateException.class, server::getListenerInfo);
        assertNotNull(beforeStart.getMessage());
        assertTrue(beforeStart.getMessage().contains("Server not started"),
                "unexpected message: " + beforeStart.getMessage());

        server.start();

        assertNotNull(server.getXnio());
        assertNotNull(server.getWorker());
        assertEquals(1, server.getListenerInfo().size());

        server.stop();

        assertNull(server.getXnio());
        assertNull(server.getWorker());
        assertThrows(IllegalStateException.class, server::getListenerInfo);
    }

    @Test
    void stopIsANoOpWhenTheServerWasNeverStarted() {
        Undertow server = track(Undertow.builder().build());

        server.stop();
        // stopping twice must not blow up either
        server.stop();

        assertNull(server.getWorker());
        assertNull(server.getXnio());
        assertThrows(IllegalStateException.class, server::getListenerInfo);
    }

    @Test
    void aServerInstanceCanBeRestartedAfterItWasStopped() throws Exception {
        Undertow server = track(Undertow.builder()
                .addHttpListener(0, HOST)
                .setHandler(textHandler("restartable"))
                .build());

        server.start();
        XnioWorker firstWorker = server.getWorker();
        assertNotNull(firstWorker);
        assertEquals("restartable", get(portOf(server.getListenerInfo().get(0)), "/first").body);

        server.stop();
        assertNull(server.getWorker());
        assertTrue(firstWorker.isShutdown());

        server.start();
        XnioWorker secondWorker = server.getWorker();
        assertNotNull(secondWorker);
        assertNotSame(firstWorker, secondWorker, "a fresh internal worker is created on every start");
        assertTrue(secondWorker.getIoThreadCount() > 0);
        assertEquals("restartable", get(portOf(server.getListenerInfo().get(0)), "/second").body);
    }

    // ------------------------------------------------------------------
    // HTTP listeners
    // ------------------------------------------------------------------

    @Test
    void httpListenerServesRequestsAndExposesListenerInfo() throws Exception {
        AtomicInteger invocations = new AtomicInteger();
        Undertow server = track(Undertow.builder()
                .addHttpListener(0, HOST)
                .setHandler(exchange -> {
                    invocations.incrementAndGet();
                    respond(exchange, "path=" + exchange.getRequestPath());
                })
                .build());

        server.start();

        List<Undertow.ListenerInfo> listenerInfo = server.getListenerInfo();
        assertEquals(1, listenerInfo.size());
        Undertow.ListenerInfo info = listenerInfo.get(0);

        assertEquals("http", info.getProtcol());
        assertFalse(info.isSuspended());
        assertNull(info.getSslContext(), "a plain http listener has no ssl context");
        assertNull(info.getConnectorStatistics(), "connector statistics are disabled by default");
        assertTrue(info.toString().contains("http"), info.toString());
        assertTrue(info.toString().contains(String.valueOf(portOf(info))), info.toString());

        HttpResponse response = get(portOf(info), "/the/path");
        assertEquals(200, response.status);
        assertEquals("path=/the/path", response.body);
        assertEquals(1, invocations.get());

        // the listener info list is a read only view of the server state
        assertThrows(UnsupportedOperationException.class, () -> server.getListenerInfo().add(info));

        // socket option changes are delegated to the accepting channel and keep the listener usable
        info.setSocketOption(Options.TCP_NODELAY, Boolean.TRUE);
        info.setSocketOption(Options.REUSE_ADDRESSES, Boolean.TRUE);

        HttpResponse secondResponse = get(portOf(info), "/again");
        assertEquals(200, secondResponse.status);
        assertEquals("path=/again", secondResponse.body);
        assertEquals(2, invocations.get());
    }

    @Test
    void listenerRootHandlerOverridesTheServerRootHandler() throws Exception {
        Undertow server = track(Undertow.builder()
                .setHandler(textHandler("server-handler"))
                .addHttpListener(0, HOST)
                .addHttpListener(0, HOST, textHandler("listener-handler"))
                .build());

        server.start();

        List<Undertow.ListenerInfo> listenerInfo = server.getListenerInfo();
        assertEquals(2, listenerInfo.size());

        HttpResponse global = get(portOf(listenerInfo.get(0)), "/");
        assertEquals(200, global.status);
        assertEquals("server-handler", global.body);

        HttpResponse specific = get(portOf(listenerInfo.get(1)), "/");
        assertEquals(200, specific.status);
        assertEquals("listener-handler", specific.body);
    }

    @Test
    void connectorStatisticsCanBeEnabledThroughListenerInfo() throws Exception {
        Undertow server = track(Undertow.builder()
                .addHttpListener(0, HOST)
                .setHandler(textHandler("counting"))
                .build());

        server.start();

        Undertow.ListenerInfo info = server.getListenerInfo().get(0);
        assertNull(info.getConnectorStatistics());

        info.setServerOptions(OptionMap.create(UndertowOptions.ENABLE_CONNECTOR_STATISTICS, Boolean.TRUE));

        ConnectorStatistics statistics = info.getConnectorStatistics();
        assertNotNull(statistics, "statistics must be available once enabled on the open listener");
        assertEquals(0L, statistics.getRequestCount());

        assertEquals(200, get(portOf(info), "/counted").status);

        assertEquals(1L, statistics.getRequestCount());
        assertTrue(statistics.getBytesSent() > 0, "response bytes must be accounted for");
        assertTrue(statistics.getBytesReceived() > 0, "request bytes must be accounted for");

        statistics.reset();
        assertEquals(0L, statistics.getRequestCount());
    }

