    // ------------------------------------------------------------------
    // HTTPS / AJP listeners
    // ------------------------------------------------------------------

    @Test
    void httpsListenerServesTlsRequestsAndExposesItsSslContext() throws Exception {
        SSLContext sslContext = serverSslContext();
        Undertow server = track(Undertow.builder()
                .addHttpsListener(0, HOST, sslContext)
                .setHandler(textHandler("secure"))
                .build());

        server.start();

        Undertow.ListenerInfo info = server.getListenerInfo().get(0);
        assertEquals("https", info.getProtcol());
        assertSame(sslContext, info.getSslContext());

        HttpResponse response = getTls(portOf(info), "/secure");
        assertEquals(200, response.status);
        assertEquals("secure", response.body);

        SSLContext replacement = serverSslContext();
        info.setSslContext(replacement);
        assertSame(replacement, info.getSslContext());

        // the updated context is used for new connections
        HttpResponse afterUpdate = getTls(portOf(info), "/updated");
        assertEquals(200, afterUpdate.status);
        assertEquals("secure", afterUpdate.body);

        // a plain http listener silently ignores attempts to set an ssl context
        Undertow plainServer = track(Undertow.builder()
                .addHttpListener(0, HOST)
                .setHandler(textHandler("plain"))
                .build());
        plainServer.start();
        Undertow.ListenerInfo plainInfo = plainServer.getListenerInfo().get(0);
        plainInfo.setSslContext(replacement);
        assertNull(plainInfo.getSslContext());
        assertEquals(200, get(portOf(plainInfo), "/").status);
    }

