    @Test
    void proxyProtocolListenerRequiresAProxyHeader() throws Exception {
        Undertow server = track(Undertow.builder()
                .addListener(new Undertow.ListenerBuilder()
                        .setType(Undertow.ListenerType.HTTP)
                        .setHost(HOST)
                        .setPort(0)
                        .setUseProxyProtocol(true)
                        .setRootHandler(textHandler("proxied")))
                .setHandler(textHandler("ignored"))
                .build());

        server.start();

        int port = portOf(server.getListenerInfo().get(0));

        // a request without the PROXY preamble is rejected without an HTTP response
        byte[] rejected = exchangeAndReadAll(port,
                "GET / HTTP/1.1\r\nHost: localhost\r\nConnection: close\r\n\r\n");
        assertEquals(0, rejected.length,
                "connections without a proxy protocol header must be closed without a response");

        // with the PROXY preamble the request is handed to the configured handler
        String accepted = new String(exchangeAndReadAll(port,
                "PROXY TCP4 192.168.0.1 192.168.0.11 56324 80\r\n"
                        + "GET / HTTP/1.1\r\nHost: localhost\r\nConnection: close\r\n\r\n"),
                StandardCharsets.ISO_8859_1);
        assertTrue(accepted.startsWith("HTTP/1.1 200"), accepted);
        assertTrue(accepted.contains("proxied"), accepted);
    }

    // ------------------------------------------------------------------
    // suspend / resume
    // ------------------------------------------------------------------

    @Test
    void suspendClosesConnectionsAndResumeRestoresService() throws Exception {
        Undertow server = track(Undertow.builder()
                .addHttpListener(0, HOST)
                .setHandler(textHandler("suspendable"))
                .build());

        server.start();

        Undertow.ListenerInfo info = server.getListenerInfo().get(0);
        int port = portOf(info);
        assertFalse(info.isSuspended());

        try (Socket socket = new Socket()) {
            socket.connect(new InetSocketAddress(HOST, port), 10_000);
            socket.setSoTimeout(10_000);
            // keep the connection alive: only suspend() may close it
            writeRequest(socket, getRequest("/keepalive", true));
            HttpResponse first = readResponse(socket.getInputStream());
            assertEquals(200, first.status);
            assertEquals("suspendable", first.body);

            info.suspend();
            assertTrue(info.isSuspended());

            // suspending closes the connections that the listener is keeping alive
            int read;
            try {
                read = socket.getInputStream().read();
            } catch (SocketException e) {
                read = -1;
            }
            assertEquals(-1, read, "the connection must be closed once the listener is suspended");
        }

        info.resume();
        assertFalse(info.isSuspended());

        HttpResponse afterResume = get(port, "/resumed");
        assertEquals(200, afterResume.status);
        assertEquals("suspendable", afterResume.body);
    }

    // ------------------------------------------------------------------
    // stop / worker handling
    // ------------------------------------------------------------------

    @Test
    void stopClosesTheListenersAndShutsDownTheInternalWorker() throws Exception {
        Undertow server = track(Undertow.builder()
                .addHttpListener(0, HOST)
                .setHandler(textHandler("stoppable"))
                .setServerOption(UndertowOptions.SHUTDOWN_TIMEOUT, Integer.valueOf(10_000))
                .build());

        server.start();

        int port = portOf(server.getListenerInfo().get(0));
        XnioWorker worker = server.getWorker();
        assertNotNull(worker);
        assertFalse(worker.isShutdown());
        assertEquals(200, get(port, "/before-stop").status);

        server.stop();

        assertTrue(worker.isShutdown(), "the worker created by start() must be shut down by stop()");
        assertNull(server.getWorker());
        assertNull(server.getXnio());
        assertThrows(IllegalStateException.class, server::getListenerInfo);
        assertThrows(IOException.class, () -> get(port, "/after-stop"));

        // stop() is idempotent
        server.stop();
    }

    @Test
    void externallySuppliedWorkerIsReusedAndSurvivesStop() throws Exception {
        Xnio xnio = Xnio.getInstance(UndertowTests.class.getClassLoader());
        XnioWorker worker = xnio.createWorker(OptionMap.create(Options.WORKER_IO_THREADS, Integer.valueOf(1)));
        assertNotNull(worker);
        try {
            Undertow first = track(Undertow.builder()
                    .setWorker(worker)
                    .addHttpListener(0, HOST)
                    .setHandler(textHandler("shared-worker"))
                    .build());

            assertSame(worker, first.getWorker(), "the builder worker is exposed before start");

            first.start();
            assertSame(worker, first.getWorker());
            assertEquals(200, get(portOf(first.getListenerInfo().get(0)), "/first").status);

            first.stop();

            assertFalse(worker.isShutdown(), "an externally supplied worker must not be shut down by stop()");
            assertFalse(worker.awaitTermination(50, TimeUnit.MILLISECONDS));
            assertSame(worker, first.getWorker());

            // the worker is still usable for a new server instance
            Undertow second = track(Undertow.builder()
                    .setWorker(worker)
                    .addHttpListener(0, HOST)
                    .setHandler(textHandler("second-server"))
                    .build());
            second.start();
            HttpResponse response = get(portOf(second.getListenerInfo().get(0)), "/second");
            assertEquals(200, response.status);
            assertEquals("second-server", response.body);
            second.stop();

            assertFalse(worker.isShutdown());
        } finally {
            worker.shutdown();
            worker.awaitTermination();
        }
    }

    @Test
    void failedStartShutsDownTheInternalWorkerAndThrows() throws Exception {
        try (ServerSocket blocker = new ServerSocket(0, 1, java.net.InetAddress.getByName(HOST))) {
            int port = blocker.getLocalPort();

            Undertow server = track(Undertow.builder()
                    .addHttpListener(port, HOST)
                    .setHandler(textHandler("never-served"))
                    .build());

            RuntimeException failure = assertThrows(RuntimeException.class, server::start);
            assertNotNull(findCause(failure, BindException.class),
                    "expected a BindException in the cause chain of " + failure);

            XnioWorker worker = server.getWorker();
            assertNotNull(worker);
            assertTrue(worker.isShutdown(), "the worker must be shut down when start() fails");
            // a failed start leaves the (empty) listener list behind instead of reporting "not started"
            assertTrue(server.getListenerInfo().isEmpty());
        }
    }

    @Test
    void workerIoThreadsCanBeConfiguredThroughTheBuilder() throws Exception {
        Undertow first = track(Undertow.builder()
                .setIoThreads(2)
                .setWorkerThreads(2)
                .addHttpListener(0, HOST)
                .setHandler(textHandler("threads"))
                .build());
        first.start();

        XnioWorker configured = first.getWorker();
        assertNotNull(configured);
        assertEquals(2, configured.getIoThreadCount());
        assertEquals(200, get(portOf(first.getListenerInfo().get(0)), "/threads").status);

        first.stop();
        assertTrue(configured.isShutdown());

        Undertow overridden = track(Undertow.builder()
                .setIoThreads(4)
                .setWorkerThreads(4)
                .setWorkerOption(Options.WORKER_IO_THREADS, Integer.valueOf(1))
                .addHttpListener(0, HOST)
                .setHandler(textHandler("threads"))
                .build());
        overridden.start();

        assertNotNull(overridden.getWorker());
        assertEquals(1, overridden.getWorker().getIoThreadCount(),
                "explicit worker options must win over setIoThreads()");
        assertEquals(200, get(portOf(overridden.getListenerInfo().get(0)), "/threads").status);
    }

    // ------------------------------------------------------------------
    // HTTP/2 upgrade
    // ------------------------------------------------------------------

    @Test
    void http2UpgradeIsOfferedWhenEnabledThroughAServerOption() throws Exception {
        Undertow server = track(Undertow.builder()
                .addHttpListener(0, HOST)
                .setHandler(textHandler("h2c-server-option"))
                .setServerOption(UndertowOptions.ENABLE_HTTP2, Boolean.TRUE)
                .build());

        server.start();

        int port = portOf(server.getListenerInfo().get(0));

        // plain requests are still served by the handler chain
        assertEquals("h2c-server-option", get(port, "/plain").body);

        HttpResponse upgrade = exchange(port, upgradeRequest("/upgrade"));
        assertEquals(101, upgrade.status);
        assertEquals("h2c", upgrade.header("upgrade"));
    }

    @Test
    void http2UpgradeIsOfferedWhenEnabledOnTheListener() throws Exception {
        Undertow server = track(Undertow.builder()
                .addListener(new Undertow.ListenerBuilder()
                        .setType(Undertow.ListenerType.HTTP)
                        .setHost(HOST)
                        .setPort(0)
                        .setHttp2Enabled(true)
                        .setOverrideSocketOptions(OptionMap.create(Options.TCP_NODELAY, Boolean.TRUE))
                        .setRootHandler(textHandler("h2c-listener")))
                .setHandler(textHandler("ignored"))
                .build());

        server.start();

        int port = portOf(server.getListenerInfo().get(0));

        HttpResponse plain = get(port, "/plain");
        assertEquals(200, plain.status);
        assertEquals("h2c-listener", plain.body);

        HttpResponse upgrade = exchange(port, upgradeRequest("/upgrade"));
        assertEquals(101, upgrade.status);
        assertEquals("h2c", upgrade.header("upgrade"));
    }

    @Test
    void http2UpgradeIsNotOfferedByDefault() throws Exception {
        Undertow server = track(Undertow.builder()
                .addHttpListener(0, HOST)
                .setHandler(textHandler("http1-only"))
                .build());

        server.start();

        int port = portOf(server.getListenerInfo().get(0));

        HttpResponse response = exchange(port, upgradeRequest("/upgrade"));
        assertEquals(200, response.status, "without http2 enabled the upgrade header is passed to the handler");
        assertEquals("http1-only", response.body);
    }

    // ------------------------------------------------------------------
    // helpers
    // ------------------------------------------------------------------

    private Undertow track(Undertow server) {
        servers.add(server);
        return server;
    }

    private static HttpHandler textHandler(String text) {
        return exchange -> respond(exchange, text);
    }

    private static void respond(HttpServerExchange exchange, String text) {
        byte[] bytes = text.getBytes(StandardCharsets.UTF_8);
        exchange.setStatusCode(200);
        exchange.getResponseHeaders().put(Headers.CONTENT_TYPE, "text/plain; charset=utf-8");
        exchange.getResponseHeaders().put(Headers.CONTENT_LENGTH, Integer.toString(bytes.length));
        exchange.getResponseSender().send(ByteBuffer.wrap(bytes));
    }

    private static int portOf(Undertow.ListenerInfo info) {
        SocketAddress address = info.getAddress();
        assertNotNull(address, "the listener info must expose the bound address");
        assertTrue(address instanceof InetSocketAddress, "unexpected address type " + address.getClass());
