    @Test
    void http2UpgradeIsOfferedWhenEnabledOnTheListener() throws Exception {
        Undertow server = track(Undertow.builder()
                .addListener(new Undertow.ListenerBuilder()
                        .setType(Undertow.ListenerType.HTTP)
                        .setHost(HOST)
                        .setPort(0)
                        .setHttp2Enabled(true)
                        .setOverrideSocketOptions(OptionMap.create(Options.TCP_NODELAY, Boolean.TRUE))
                        .setRootHandler(textHandler("h2c-listener")))
