                    .set(UndertowOptions.HTTP2_SETTINGS_INITIAL_WINDOW_SIZE, 1234)
                    .set(UndertowOptions.HTTP2_SETTINGS_MAX_CONCURRENT_STREAMS, 7)
                    .set(UndertowOptions.HTTP2_SETTINGS_MAX_FRAME_SIZE, 32768)
                    .set(UndertowOptions.HTTP2_SETTINGS_ENABLE_PUSH, false)
                    .set(UndertowOptions.MAX_HEADERS, 5)
                    .getMap();
            Http2Channel server = new Http2Channel(endpoint, "custom-protocol", bufferPool, null, false, false, options);
            channel = server;

            assertEquals(1234, server.getInitialReceiveWindowSize());
            assertEquals(7, server.getReceiveMaxConcurrentStreams());
            assertEquals(32768, server.getReceiveMaxFrameSize());
            assertFalse(server.isPushEnabled());
            assertEquals("custom-protocol", server.getProtocol());
            assertEquals(5, server.getMaxHeaders());
        });
