                    .set(UndertowOptions.MAX_RST_FRAMES_PER_WINDOW, 2)
                    .set(UndertowOptions.RST_FRAMES_TIME_WINDOW, Integer.MAX_VALUE)
                    .getMap();
            Http2Channel server = newServer(false, options);

            server.sendRstStream(1, Http2Channel.ERROR_CANCEL);
            server.sendRstStream(3, Http2Channel.ERROR_CANCEL);
            assertFalse(server.isThisGoneAway());
            server.sendRstStream(5, Http2Channel.ERROR_CANCEL);
            assertTrue(server.isThisGoneAway());

            Frame first = readFrame();
            assertEquals(Http2Channel.FRAME_TYPE_RST_STREAM, first.type);
            assertEquals(1, first.streamId);
            Frame second = readFrame();
            assertEquals(Http2Channel.FRAME_TYPE_RST_STREAM, second.type);
            assertEquals(3, second.streamId);
            Frame goAway = readFrame();
            assertEquals(Http2Channel.FRAME_TYPE_GOAWAY, goAway.type);
            assertEquals(Http2Channel.ERROR_ENHANCE_YOUR_CALM, goAway.intAt(4));
        });
