    @Test
    void receiveSettingsFrameUpdatesStateAndAcknowledges() throws IOException {
        runOnIoThread(() -> {
            Http2Channel server = newServerWithoutPreface(OptionMap.EMPTY);
            writeToPeer(frame(Http2Channel.FRAME_TYPE_SETTINGS, 0, 0, settingsPayload(
                    Http2Setting.SETTINGS_MAX_FRAME_SIZE, 32768,
                    Http2Setting.SETTINGS_INITIAL_WINDOW_SIZE, 1000,
                    Http2Setting.SETTINGS_MAX_CONCURRENT_STREAMS, 3,
                    Http2Setting.SETTINGS_ENABLE_PUSH, 0)));

            AbstractHttp2StreamSourceChannel received = server.receive();
            Http2SettingsStreamSourceChannel settings = assertInstanceOf(Http2SettingsStreamSourceChannel.class, received);
            assertEquals(4, settings.getSettings().size());
            assertEquals(32768, server.getSendMaxFrameSize());
            assertEquals(1000, server.getInitialSendWindowSize());
            assertEquals(3, server.getSendMaxConcurrentStreams());
            assertFalse(server.isPushEnabled());

            Frame serverSettings = readFrame();
            assertEquals(Http2Channel.FRAME_TYPE_SETTINGS, serverSettings.type);
