    private Http2Channel newServerWithoutPreface(OptionMap settings) {
        channel = new Http2Channel(endpoint, null, bufferPool, null, false, false, false, settings);
        return channel;
    }

    private Http2Channel newClient(boolean fromUpgrade, OptionMap settings) {
        channel = new Http2Channel(endpoint, null, bufferPool, null, true, fromUpgrade, settings);
        return channel;
    }

    private void initializePeer(Http2Channel server) throws IOException {
        writeToPeer(frame(Http2Channel.FRAME_TYPE_SETTINGS, 0, 0, new byte[0]));
        AbstractHttp2StreamSourceChannel received = server.receive();
        assertInstanceOf(Http2SettingsStreamSourceChannel.class, received);
        IoUtils.safeClose(received);
        readFrame();
        readFrame();
    }

    private static ByteBuffer settingsPayload(int... idsAndValues) {
        ByteBuffer buffer = ByteBuffer.allocate(idsAndValues.length / 2 * 6);
        for (int i = 0; i < idsAndValues.length; i += 2) {
            buffer.putShort((short) idsAndValues[i]);
            buffer.putInt(idsAndValues[i + 1]);
        }
        buffer.flip();
        return buffer;
    }

    private static Map<Integer, Long> parseSettings(byte[] payload) {
        Map<Integer, Long> result = new java.util.HashMap<>();
        ByteBuffer buffer = ByteBuffer.wrap(payload);
        while (buffer.remaining() >= 6) {
            int id = buffer.getShort() & 0xffff;
            long value = buffer.getInt() & 0xffffffffL;
            result.put(id, value);
        }
        return result;
    }

    private static ByteBuffer frame(int type, int flags, int streamId, byte[] payload) {
        return frame(type, flags, streamId, payload, payload.length);
    }

    private static ByteBuffer frame(int type, int flags, int streamId, ByteBuffer payload) {
        int length = payload.remaining();
        return frame(type, flags, streamId, toByteArray(payload), length);
    }

    private static ByteBuffer frame(int type, int flags, int streamId, byte[] payload, int length) {
        ByteBuffer buffer = ByteBuffer.allocate(9 + length);
        buffer.put((byte) (length >>> 16));
        buffer.put((byte) (length >>> 8));
        buffer.put((byte) length);
        buffer.put((byte) type);
        buffer.put((byte) flags);
        buffer.putInt(streamId);
        buffer.put(payload);
        buffer.flip();
        return buffer;
    }

    private static byte[] toByteArray(ByteBuffer buffer) {
        byte[] bytes = new byte[buffer.remaining()];
        buffer.get(bytes);
        return bytes;
    }

    private void writeToPeer(ByteBuffer frame) throws IOException {
        while (frame.hasRemaining()) {
            peer.getSinkChannel().write(frame);
        }
        peer.getSinkChannel().flush();
    }

    private Frame readFrame() throws IOException {
        StreamSourceChannel source = peer.getSourceChannel();
        ByteBuffer header = ByteBuffer.allocate(9);
        readFully(source, header);
        header.flip();
        int length = ((header.get() & 0xff) << 16) | ((header.get() & 0xff) << 8) | (header.get() & 0xff);
        int type = header.get() & 0xff;
        int flags = header.get() & 0xff;
        int streamId = header.getInt() & 0x7fffffff;
        byte[] payload = new byte[length];
        readFully(source, ByteBuffer.wrap(payload));
        return new Frame(length, type, flags, streamId, payload);
    }

    private ByteBuffer readBytes(int length) throws IOException {
        ByteBuffer buffer = ByteBuffer.allocate(length);
        readFully(peer.getSourceChannel(), buffer);
        buffer.flip();
        return buffer;
    }

    private void assertNoMoreData() throws IOException {
        ByteBuffer buffer = ByteBuffer.allocate(1);
        int read = peer.getSourceChannel().read(buffer);
        assertTrue(read <= 0, "Expected no more data but read " + read + " byte(s)");
    }

    private static void readFully(StreamSourceChannel source, ByteBuffer buffer) throws IOException {
        int emptyReads = 0;
        while (buffer.hasRemaining()) {
            int read = source.read(buffer);
            if (read < 0) {
                throw new EOFException("Unexpected end of stream with " + buffer.remaining() + " byte(s) remaining");
            }
            if (read == 0) {
                if (++emptyReads > 1000) {
                    throw new EOFException("No data available with " + buffer.remaining() + " byte(s) remaining");
                }
                Thread.yield();
            } else {
                emptyReads = 0;
            }
        }
    }

    private void runOnIoThread(ThrowingRunnable task) {
        FutureTask<Void> future = new FutureTask<>(() -> {
            task.run();
            return null;
        });
        ioThread.execute(future);
        try {
            future.get(15, TimeUnit.SECONDS);
        } catch (ExecutionException e) {
            Throwable cause = e.getCause();
            if (cause instanceof Error) {
                throw (Error) cause;
            }
            if (cause instanceof RuntimeException) {
                throw (RuntimeException) cause;
            }
            throw new RuntimeException(cause);
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
            throw new AssertionError("Interrupted while waiting for IO thread", e);
        } catch (TimeoutException e) {
            throw new AssertionError("Timed out waiting for IO thread", e);
        }
    }

    @FunctionalInterface
    private interface ThrowingRunnable {
        void run() throws Exception;
    }

    private static final class Frame {
        private final int length;
        private final int type;
        private final int flags;
        private final int streamId;
        private final byte[] payload;

        private Frame(int length, int type, int flags, int streamId, byte[] payload) {
            this.length = length;
            this.type = type;
            this.flags = flags;
            this.streamId = streamId;
            this.payload = payload;
        }

        private int intAt(int offset) {
            return ByteBuffer.wrap(payload).getInt(offset);
        }
    }
}

