        final ByteBuffer complete = RequestBuilder.request()
                .method(4)
                .protocol("HTTP/1.1")
                .uri("/split")
                .remoteAddress("127.0.0.1")
                .serverName("localhost")
                .serverPort(9090)
                .ssl(true)
                .codedHeader(0xB, "localhost:9090")
                .header("X-Split", "yes")
                .attribute(AjpRequestParser.QUERY_STRING, "x=1")
                .buffer();
        final byte[] data = toBytes(complete);

        final AjpRequestParser parser = newParser();
        final AjpRequestParseState state = new AjpRequestParseState();
        final HttpServerExchange exchange = new HttpServerExchange(null);

        // after half of the message the parser must still be mid-request
        final int half = data.length / 2;
        parser.parse(ByteBuffer.wrap(data, 0, half), state, exchange);
        assertFalse(state.isComplete());

        for (int i = half; i < data.length; i++) {
            parser.parse(ByteBuffer.wrap(new byte[] { data[i] }), state, exchange);
        }

        assertTrue(state.isComplete());
        assertEquals(Methods.POST, exchange.getRequestMethod());
        assertEquals(Protocols.HTTP_1_1, exchange.getProtocol());
        assertEquals("/split", exchange.getRequestPath());
        assertEquals("https", exchange.getRequestScheme());
        assertEquals("localhost:9090", exchange.getRequestHeaders().getFirst(Headers.HOST));
        assertEquals("yes", exchange.getRequestHeaders().getFirst(new HttpString("X-Split")));
        assertEquals("127.0.0.1", state.remoteAddress);
        assertEquals(9090, state.serverPort);
        assertEquals("1", exchange.getQueryParameters().get("x").getFirst());
    }

