    private static AjpRequestParser newParser() {
        return new AjpRequestParser("UTF-8", true, MAX_PARAMETERS, MAX_HEADERS, false, false);
    }

    private static byte[] toBytes(final ByteBuffer buffer) {
        final ByteBuffer copy = buffer.duplicate();
        final byte[] data = new byte[copy.remaining()];
        copy.get(data);
        return data;
    }

    private static byte[] string(String value) {
        if (value == null) {
            return new byte[] { (byte) 0xFF, (byte) 0xFF };
        }
        final byte[] bytes = value.getBytes(StandardCharsets.UTF_8);
        final byte[] data = new byte[bytes.length + 3];
        data[0] = (byte) ((bytes.length >> 8) & 0xFF);
        data[1] = (byte) (bytes.length & 0xFF);
        System.arraycopy(bytes, 0, data, 2, bytes.length);
        data[data.length - 1] = 0x00;
        return data;
    }

    private static byte[] int16(int value) {
        return new byte[] { (byte) ((value >> 8) & 0xFF), (byte) (value & 0xFF) };
    }

    private static byte[] concat(final byte[]... parts) {
        final ByteArrayOutputStream out = new ByteArrayOutputStream();
        for (byte[] part : parts) {
            out.write(part, 0, part.length);
        }
        return out.toByteArray();
    }

    /**
     * Builds an AJP13 forward request message (magic number, payload size, and body).
     */
    private static final class RequestBuilder {

        private int method = 2;
        private String protocol = "HTTP/1.1";
        private String uri = "/";
        private String remoteAddress = "127.0.0.1";
        private String remoteHost = "localhost";
        private String serverName = "localhost";
        private int serverPort = 8080;
        private boolean ssl;
        private final List<byte[]> headers = new ArrayList<>();
        private final List<byte[]> attributes = new ArrayList<>();

        static RequestBuilder request() {
            return new RequestBuilder();
        }

        RequestBuilder method(int method) {
            this.method = method;
            return this;
        }

        RequestBuilder protocol(String protocol) {
            this.protocol = protocol;
            return this;
        }

        RequestBuilder uri(String uri) {
            this.uri = uri;
            return this;
        }

        RequestBuilder remoteAddress(String remoteAddress) {
            this.remoteAddress = remoteAddress;
            return this;
        }

        RequestBuilder remoteHost(String remoteHost) {
            this.remoteHost = remoteHost;
            return this;
        }

        RequestBuilder serverName(String serverName) {
            this.serverName = serverName;
            return this;
        }

        RequestBuilder serverPort(int serverPort) {
            this.serverPort = serverPort;
            return this;
        }

        RequestBuilder ssl(boolean ssl) {
            this.ssl = ssl;
            return this;
        }

        RequestBuilder codedHeader(int offset, String value) {
            headers.add(concat(new byte[] { (byte) 0xA0, (byte) offset }, string(value)));
            return this;
        }

        RequestBuilder header(String name, String value) {
            headers.add(concat(string(name), string(value)));
            return this;
        }

        RequestBuilder attribute(String name, String value) {
            attributes.add(concat(new byte[] { (byte) attributeCode(name) }, string(value)));
            return this;
        }

        RequestBuilder integerAttribute(String name, int value) {
            attributes.add(concat(new byte[] { (byte) attributeCode(name) }, int16(value)));
            return this;
        }

        private static int attributeCode(String name) {
            if (AjpRequestParser.CONTEXT.equals(name)) {
                return 1;
            } else if (AjpRequestParser.SERVLET_PATH.equals(name)) {
                return 2;
            } else if (AjpRequestParser.REMOTE_USER.equals(name)) {
                return 3;
            } else if (AjpRequestParser.AUTH_TYPE.equals(name)) {
                return 4;
            } else if (AjpRequestParser.QUERY_STRING.equals(name)) {
                return 5;
            } else if (AjpRequestParser.ROUTE.equals(name)) {
                return 6;
            } else if (AjpRequestParser.SSL_CERT.equals(name)) {
                return 7;
            } else if (AjpRequestParser.SSL_CIPHER.equals(name)) {
                return 8;
            } else if (AjpRequestParser.SSL_SESSION.equals(name)) {
                return 9;
            } else if (AjpRequestParser.REQ_ATTRIBUTE.equals(name)) {
                return 10;
            } else if (AjpRequestParser.SSL_KEY_SIZE.equals(name)) {
                return 11;
            } else if (AjpRequestParser.SECRET.equals(name)) {
                return 12;
            } else if (AjpRequestParser.STORED_METHOD.equals(name)) {
                return 13;
            }
            throw new IllegalArgumentException("Unknown AJP attribute name " + name);
        }

        RequestBuilder rawAttribute(int code) {
            attributes.add(new byte[] { (byte) code });
            return this;
        }

        RequestBuilder requestAttribute(String name, String value) {
            attributes.add(concat(new byte[] { (byte) REQUEST_ATTRIBUTE_CODE }, string(name), string(value)));
            return this;
        }

        ByteBuffer buffer() {
            final ByteArrayOutputStream body = new ByteArrayOutputStream();
            body.write(AjpRequestParser.FORWARD_REQUEST);
            body.write(method);
            write(body, string(protocol));
            write(body, string(uri));
            write(body, string(remoteAddress));
            write(body, string(remoteHost));
            write(body, string(serverName));
            write(body, int16(serverPort));
            body.write(ssl ? 1 : 0);
            write(body, int16(headers.size()));
            for (byte[] header : headers) {
                write(body, header);
            }
            for (byte[] attribute : attributes) {
                write(body, attribute);
            }
            body.write(ATTRIBUTE_TERMINATOR);

            final byte[] payload = body.toByteArray();
            final ByteArrayOutputStream message = new ByteArrayOutputStream();
            write(message, int16(0x1234));
            write(message, int16(payload.length));
            write(message, payload);
            return ByteBuffer.wrap(message.toByteArray());
        }

        private static void write(ByteArrayOutputStream out, byte[] data) {
            out.write(data, 0, data.length);
        }
    }
}

