    @Test
    void rejectsControlFrameWithPayloadLongerThan125Bytes() {
        WebSocket07Channel channel = newChannel(true, false, NoopExtensionFunction.INSTANCE);
        assertRejected(channel, "Control frame with payload length > 125 octets", 0x89, 126);
    }

    @Test
    void rejectsReservedControlOpcode() {
        WebSocket07Channel channel = newChannel(true, false, NoopExtensionFunction.INSTANCE);
        assertRejected(channel, "Control frame using reserved opcode = 11", 0x8B, 0);
    }

    @Test
    void rejectsOneByteCloseFramePayload() {
        WebSocket07Channel channel = newChannel(true, false, NoopExtensionFunction.INSTANCE);
        assertRejected(channel, "Received close control frame with payload len 1", 0x88, 1);
    }

    @Test
    void rejectsReservedBitsWhenExtensionsAreNotEnabled() {
        WebSocket07Channel channel = newChannel(true, false, NoopExtensionFunction.INSTANCE);
        assertRejected(channel, "Extensions not allowed but received rsv of 1", 0x91, 0);
    }

    @Test
    void acceptsReservedBitsAndPropagatesThemWhenExtensionsAreEnabled() throws IOException {
        ExtensionFunction extension = new NoopExtensionFunction();
        WebSocket07Channel channel = newChannel(true, true, extension);
        WebSocket07Channel.WebSocketFrameHeader frame = newFrame(channel);

        feed(frame, 0x91, 0);

        StreamSourceFrameChannel source = frame.getChannel(null);
        assertInstanceOf(WebSocket07TextFrameSourceChannel.class, source);
        assertEquals(1, source.getRsv());
        assertSame(extension, source.getWebSocketChannel().getExtensionFunction());
    }

    @Test
    void rejectsUnmaskedClientToServerDataFrame() {
        WebSocket07Channel channel = newChannel(false, false, NoopExtensionFunction.INSTANCE);
        assertRejected(channel, "Web socket frame was not masked", 0x81, 0);
    }

    @Test
    void rejectsReservedDataOpcode() {
        WebSocket07Channel channel = newChannel(true, false, NoopExtensionFunction.INSTANCE);
        assertRejected(channel, "Data frame using reserved opcode = 3", 0x83, 0);
    }

    @Test
    void rejectsContinuationFrameOutsideFragmentedMessage() {
        WebSocket07Channel channel = newChannel(true, false, NoopExtensionFunction.INSTANCE);
        assertRejected(channel, "Received continuation data frame outside fragmented message", 0x80, 0);
    }

    @Test
    void rejectsNewDataFrameWhileInsideFragmentedMessage() throws WebSocketException {
        WebSocket07Channel channel = newChannel(true, false, NoopExtensionFunction.INSTANCE);
        WebSocket07Channel.WebSocketFrameHeader first = newFrame(channel);
        feed(first, 0x01, 0);
        assertTrue(first.isDone());
        assertFalse(first.isFinalFragment());

        assertRejected(channel, "Received non-continuation data frame while inside fragmented message",
                0x81, 0);
    }

    @Test
    void pingAndPongDoNotEndAFragmentedMessage() throws WebSocketException {
        WebSocket07Channel channel = newChannel(true, false, NoopExtensionFunction.INSTANCE);
        WebSocket07Channel.WebSocketFrameHeader first = newFrame(channel);
        feed(first, 0x01, 0);

        WebSocket07Channel.WebSocketFrameHeader ping = newFrame(channel);
        feed(ping, 0x89, 0);
        assertTrue(ping.isDone());

        assertRejected(channel, "Received non-continuation data frame while inside fragmented message",
                0x81, 0);
    }

    @Test
    void finalContinuationEndsFragmentedMessage() throws WebSocketException {
        WebSocket07Channel channel = newChannel(true, false, NoopExtensionFunction.INSTANCE);

        WebSocket07Channel.WebSocketFrameHeader first = newFrame(channel);
        feed(first, 0x01, 0);

        WebSocket07Channel.WebSocketFrameHeader last = newFrame(channel);
        feed(last, 0x80, 0);
        assertTrue(last.isFinalFragment());

        assertRejected(channel, "Received continuation data frame outside fragmented message", 0x80, 0);
    }

    @Test
    void exposesExistingChannelForContinuationFramesAndClearsItOnFinalFrame() throws IOException {
        WebSocket07Channel channel = newChannel(true, false, NoopExtensionFunction.INSTANCE);

        WebSocket07Channel.WebSocketFrameHeader firstHeader = newFrame(channel);
        feed(firstHeader, 0x01, 0);
        StreamSourceFrameChannel first = firstHeader.getChannel(null);
        assertFalse(first.isFinalFragment());
        assertNull(firstHeader.getExistingChannel());

        WebSocket07Channel.WebSocketFrameHeader continuation = newFrame(channel);
        feed(continuation, 0x80, 0);
        assertTrue(continuation.isFinalFragment());
        assertSame(first, continuation.getExistingChannel());
        assertNull(continuation.getExistingChannel());
    }

    @Test
    void closesTheFragmentedChannelWhenSubChannelsAreClosed() throws IOException {
        WebSocket07Channel channel = newChannel(true, false, NoopExtensionFunction.INSTANCE);
        WebSocket07Channel.WebSocketFrameHeader firstHeader = newFrame(channel);
        feed(firstHeader, 0x01, 0);
        StreamSourceFrameChannel first = firstHeader.getChannel(null);

        assertTrue(first.isOpen());
        channel.closeSubChannels();
        assertFalse(first.isOpen());
    }

    @Test
    void markingReadsBrokenMarksTheChannelAndClosesSubChannels() throws IOException {
        TestWebSocket07Channel channel = newChannel(true, false, NoopExtensionFunction.INSTANCE);
        WebSocket07Channel.WebSocketFrameHeader firstHeader = newFrame(channel);
        feed(firstHeader, 0x01, 0);
        StreamSourceFrameChannel first = firstHeader.getChannel(null);

        assertFalse(channel.readsAreBroken());
        channel.markReadsBroken(new IOException("read failure"));

        assertTrue(channel.readsAreBroken());
        assertFalse(first.isOpen());
    }

    private void assertSinkChannel(WebSocketFrameType type,
                                   Class<? extends StreamSinkFrameChannel> expectedType) throws IOException {
        WebSocket07Channel channel = newChannel(true, true, NoopExtensionFunction.INSTANCE);
        StreamSinkFrameChannel sink = channel.send(type);

        assertEquals(expectedType, sink.getClass());
        assertEquals(type, sink.getType());
        assertSame(channel, sink.getWebSocketChannel());
    }

    private void assertControlChannel(WebSocket07Channel channel, int firstByte,
                                      WebSocketFrameType expectedFrameType,
                                      Class<? extends StreamSourceFrameChannel> expectedChannelType)
            throws IOException {
        WebSocket07Channel.WebSocketFrameHeader frame = newFrame(channel);
        feed(frame, firstByte, 0);

        assertTrue(frame.isDone());
        assertTrue(frame.isFinalFragment());
        assertEquals(0, frame.getFrameLength());
        StreamSourceFrameChannel source = frame.getChannel(null);
        assertEquals(expectedChannelType, source.getClass());
        assertEquals(expectedFrameType, source.getType());
    }

    private void assertRejected(WebSocket07Channel channel, String expectedMessage, int... header) {
        WebSocket07Channel.WebSocketFrameHeader frame = newFrame(channel);
        WebSocketFrameCorruptedException exception = assertThrows(WebSocketFrameCorruptedException.class,
                () -> feed(frame, header));
        assertTrue(exception.getMessage().contains(expectedMessage),
                () -> "Expected message containing '" + expectedMessage + "' but was: "
                        + exception.getMessage());
        assertFalse(frame.isDone());
    }

    private TestWebSocket07Channel newChannel(boolean client, boolean extensionsSupported,
                                          ExtensionFunction extensionFunction) {
        return newChannel(WS_URL, client, extensionsSupported, extensionFunction);
    }

    private TestWebSocket07Channel newChannel(String url, boolean client, boolean extensionsSupported,
                                          ExtensionFunction extensionFunction) {
        Set<WebSocketChannel> openConnections = new HashSet<>();
        return new TestWebSocket07Channel(connection, bufferPool, url, SUB_PROTOCOL, client,
                extensionsSupported, extensionFunction, openConnections, OptionMap.EMPTY);
    }

    private static WebSocket07Channel.WebSocketFrameHeader newFrame(WebSocket07Channel channel) {
        return (WebSocket07Channel.WebSocketFrameHeader) channel.receiveFrame();
    }

    private static void feed(WebSocket07Channel.WebSocketFrameHeader frame, int... values)
            throws WebSocketException {
        frame.handle(byteBuffer(values));
    }

    private static final class TestWebSocket07Channel extends WebSocket07Channel {
        private TestWebSocket07Channel(StreamConnection channel, ByteBufferPool bufferPool,
                                       String wsUrl, String subProtocol, boolean client,
                                       boolean allowExtensions, ExtensionFunction extensionFunction,
                                       Set<WebSocketChannel> openConnections, OptionMap options) {
            super(channel, bufferPool, wsUrl, subProtocol, client, allowExtensions,
                    extensionFunction, openConnections, options);
        }

        boolean readsAreBroken() {
            return isReadsBroken();
        }
    }

    private static ByteBuffer byteBuffer(int... values) {
        byte[] bytes = new byte[values.length];
        for (int i = 0; i < values.length; i++) {
            bytes[i] = (byte) values[i];
        }
        return ByteBuffer.wrap(bytes);
    }
}

